"""Deterministic temporary vector kit + three compact maps, no GPU or paid services.
Geometry is authored here; generated JSON is the shared source for Phaser and minimaps.
Run from repository root with Python 3. No third-party dependencies.
"""
import json
from pathlib import Path
from html import escape
import base64
OUT = Path('public/game/assets/stage3')
OUT.mkdir(parents=True, exist_ok=True)

def svg(name, body, w=256, h=256):
    (OUT / (name + '.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{body}</svg>')

# Each material is a small repeatable tile, not a complete background painting.
for theme, ground, path, stone, line in [
    ('aether','#234b49','#54746a','#aac1b4','#d6c585'),
    ('nexus','#172734','#314b61','#76899b','#76dcff'),
    ('pyra','#392c30','#775347','#a27b61','#f9b46e')]:
    svg(theme+'-ground',f'<rect width="64" height="64" fill="{ground}"/><path d="M0 21L18 23 25 15M46 0L41 17 64 26M0 58L23 49 38 64" fill="none" stroke="{path}" opacity=".32"/><circle cx="35" cy="33" r="1.4" fill="{line}" opacity=".3"/>',64,64)
    svg(theme+'-path',f'<rect width="64" height="64" fill="{path}"/><path d="M0 0H64V64H0ZM0 32H64M32 0V32M19 32V64" fill="none" stroke="{ground}" opacity=".45"/><path d="M4 4H29M36 37H59" stroke="{line}" opacity=".28"/>',64,64)
    svg(theme+'-plaza',f'<rect width="64" height="64" fill="{stone}"/><path d="M0 0H64V64H0ZM0 32H64M32 0V64" fill="none" stroke="{ground}" opacity=".4"/><path d="M26 32L32 26 38 32 32 38Z" fill="{line}" opacity=".5"/>',64,64)

