IDS = ['guide','hunter','merchant','smith']
def build(id, race, name, settlement, desc, architecture, spawn, market, names, roles, dialogue, objects, hazards, paths, plazas, enemies, landmarks, enemyName, huntName):
    objs=[]
    for i,(asset,x,y,w,h,fw,fh) in enumerate(objects):
        objs.append(dict(id=f'{asset}-{i}',kind=asset,asset=asset,x=x,y=y,width=w,height=h,anchorX=.5,anchorY=.92,solid=True,footprint=dict(width=fw,height=fh)))
    details = {
      'aether': [('cloud-peak',x,240,420,270) for x in (330,780,1660,2110)] + [('garden',x,y,170,120) for x,y in [(950,870),(1430,880),(810,1270),(1500,1320),(380,1180),(2020,1170),(680,650),(1780,630),(1030,1550),(1310,1530)]],
      'nexus': [('pylon',x,y,100,170) for x,y in [(340,930),(840,1020),(1400,920),(1900,880),(1500,1280),(2000,1330)]] + [('tech-garden',x,y,190,160) for x,y in [(320,1220),(920,1170),(1920,580),(1170,600),(1890,1450)]],
      'pyra': [('volcano',x,330,420,310) for x in (450,1970)] + [('clan-banner',x,y,110,180) for x,y in [(930,1180),(1510,1160),(690,1320),(1800,1360),(930,550),(1480,550)]] + [('basalt',x,y,140,140) for x,y in [(280,1170),(2180,980),(1500,1660),(880,470)]],
    }[id]
    for asset,x,y,w,h in details:
        objs.append(dict(id=f'detail-{asset}-{len(objs)}',kind=asset,asset=asset,x=x,y=y,width=w,height=h,anchorX=.5,anchorY=.92,solid=False))
    npcs=[dict(id=k,name=n,role=r,x=x,y=y,tint=t,dialogue=d) for k,n,r,(x,y),t,d in zip(IDS,names,roles,[(spawn[0]+90,spawn[1]),(market[0]+260,market[1]+100),(spawn[0]-180,spawn[1]-40),(spawn[0]+220,spawn[1]+60)],[0xa8f0cf,0xffc7a4,0xd6b3ff,0xa4d5ff],dialogue)]
    m=dict(id=id,race=race,name=name,settlement=settlement,description=desc,architecture=architecture,width=2400,height=1792,spawn=dict(x=spawn[0],y=spawn[1]),background={'aether':'#193c42','nexus':'#122536','pyra':'#35272f'}[id],minimap=f'/game/assets/stage3/{id}-minimap.svg',market=dict(x=market[0],y=market[1],radius=85,label=market[2],instruction=f'Odwiedź oznaczony punkt: {market[2]}',action=f'Podejdź: {market[2]}'),npcs=npcs,enemies=[dict(x=x,y=y) for x,y in enemies],enemyName=enemyName,huntName=huntName,landmarks=[dict(x=x,y=y,label=l,kind=k) for x,y,l,k in landmarks],objects=objs,obstacles=[dict(x=x,y=y,width=w,height=h) for x,y,w,h in hazards],terrain=dict(ground=id+'-ground',path=id+'-path',plaza=id+'-plaza',paths=[dict(x=x,y=y,width=w,height=h) for x,y,w,h in paths],plazas=[dict(x=x,y=y,width=w,height=h) for x,y,w,h in plazas]))
    Path(f'src/game/world/regions/{id}.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
    # Actual region geometry, also used for selection preview and navigational minimap.
    bg={'aether':'#234b49','nexus':'#172734','pyra':'#392c30'}[id]
    body=f'<rect width="2400" height="1792" fill="{bg}"/>'
    for rects,c in [(m['terrain']['paths'],'#698480'),(m['terrain']['plazas'],'#a8aca0'),(m['obstacles'], '#111f2c' if id!='pyra' else '#d36a3a')]:
        for o in rects: body+=f'<rect x="{o["x"]}" y="{o["y"]}" width="{o["width"]}" height="{o["height"]}" rx="10" fill="{c}"/>'
    for o in objs:
        body+=f'<image href="data:image/svg+xml;base64,{base64.b64encode((OUT / (o["asset"]+".svg")).read_bytes()).decode()}" x="{o["x"]-o["width"]/2}" y="{o["y"]-o["height"]*.92}" width="{o["width"]}" height="{o["height"]}"/>'
    for x,y,label,kind in landmarks:
        c={'settlement':'#e8dfae','energy':'#9aeedc','danger':'#ff9778'}[kind]
        body+=f'<circle cx="{x}" cy="{y}" r="24" fill="{c}"/><text x="{x}" y="{y-38}" text-anchor="middle" fill="{c}" font-family="sans-serif" font-size="42">{escape(label)}</text>'
    body+=f'<path d="M{spawn[0]-25} {spawn[1]}h50m-25 -25v50" stroke="#fff" stroke-width="14"/>'
    svg(id+'-minimap',body,2400,1792)

